import{_ as r,C as s,o as n,c as l,a3 as t,E as i}from"./chunks/framework.bGC-1KKp.js";const b=JSON.parse(`{"title":"Activité — Le trajet d'une page Web","description":"","frontmatter":{"title":"Activité — Le trajet d'une page Web","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/activite-casse-tete.md","filePath":"modules/01-faisabilite/activite-casse-tete.md"}`),o={name:"modules/01-faisabilite/activite-casse-tete.md"};function d(u,e,c,g,p,m){const a=s("TrajetCartes");return n(),l("div",null,[e[0]||(e[0]=t('<h1 id="activite-—-le-trajet-d-une-page-web" tabindex="-1">Activité — Le trajet d&#39;une page Web <a class="header-anchor" href="#activite-—-le-trajet-d-une-page-web" aria-label="Permalink to &quot;Activité — Le trajet d&#39;une page Web&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectif de l&#39;activité</strong><br> Reconstruire, avec vos propres mots, tout ce qui doit exister pour qu&#39;une personne voie le site d&#39;un restaurant sur son téléphone. </div><h2 id="mise-en-situation" tabindex="-1">Mise en situation <a class="header-anchor" href="#mise-en-situation" aria-label="Permalink to &quot;Mise en situation&quot;">​</a></h2><p>Une cliente tape <code>bistro-exemple.ca</code> dans son téléphone pour consulter le menu et réserver une table. En quelques secondes, la page s&#39;affiche. <strong>Que s&#39;est-il passé entre les deux ?</strong></p><hr><h2 id="consignes" tabindex="-1">Consignes <a class="header-anchor" href="#consignes" aria-label="Permalink to &quot;Consignes&quot;">​</a></h2><h3 id="etape-1-—-le-trajet-10-min" tabindex="-1">Étape 1 — Le trajet (10 min) <a class="header-anchor" href="#etape-1-—-le-trajet-10-min" aria-label="Permalink to &quot;Étape 1 — Le trajet (10 min)&quot;">​</a></h3><p>Placez les cartes <strong>dans l&#39;ordre du trajet</strong>, de la cliente qui tape l&#39;adresse jusqu&#39;à la page affichée.</p><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Attention</strong><br> Certaines cartes ne se placent pas directement sur le trajet. Mettez-les dans la zone <em>À côté du trajet</em> et préparez-vous à expliquer à quoi elles servent. </div><hr><h2 id="le-casse-tete" tabindex="-1">Le casse-tête <a class="header-anchor" href="#le-casse-tete" aria-label="Permalink to &quot;Le casse-tête&quot;">​</a></h2>',11)),i(a),e[1]||(e[1]=t('<div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Votre travail est conservé dans ce navigateur.</strong><br> Vous pouvez fermer l&#39;onglet et y revenir : les cartes restent où vous les avez laissées. Par contre, rien n&#39;est envoyé au professeur — notez votre trajet dans le document de votre équipe avant la mise en commun. </div><hr><h2 id="le-corrige" tabindex="-1">Le corrigé <a class="header-anchor" href="#le-corrige" aria-label="Permalink to &quot;Le corrigé&quot;">​</a></h2><details class="mb-5"><summary><strong>Voir le corrigé</strong> (à ouvrir seulement une fois votre propre trajet terminé)</summary><h3 id="le-trajet" tabindex="-1">Le trajet <a class="header-anchor" href="#le-trajet" aria-label="Permalink to &quot;Le trajet&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:left;">Carte</th><th style="text-align:left;">Ce qui se passe</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Appareil</strong></td><td style="text-align:left;">La cliente sort son téléphone. C&#39;est le point de départ de tout le trajet.</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Navigateur</strong></td><td style="text-align:left;">C&#39;est lui, et non le téléphone, qui sait comment aller chercher une page Web.</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Nom de domaine</strong></td><td style="text-align:left;">L&#39;adresse tapée, <code>bistro-exemple.ca</code>. Pour le navigateur, ce n&#39;est encore qu&#39;un texte.</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>DNS</strong></td><td style="text-align:left;">Le navigateur demande : « à quelle adresse IP se trouve ce nom ? ». Le DNS répond.</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Certificat SSL/TLS</strong></td><td style="text-align:left;">Le navigateur ouvre une connexion <strong>chiffrée</strong> vers cette adresse. C&#39;est le cadenas.</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Hébergement</strong></td><td style="text-align:left;">Le serveur où vit le site, celui qui répond à cette adresse IP.</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Plateforme</strong></td><td style="text-align:left;">Le logiciel qui tourne sur ce serveur et qui <strong>fabrique</strong> la page demandée.</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Contenus</strong></td><td style="text-align:left;">Ce que la plateforme assemble : les textes, les photos, le menu. C&#39;est ce que la cliente voulait voir.</td></tr></tbody></table><h3 id="a-cote-du-trajet" tabindex="-1">À côté du trajet <a class="header-anchor" href="#a-cote-du-trajet" aria-label="Permalink to &quot;À côté du trajet&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Carte</th><th style="text-align:left;">Pourquoi elle n&#39;est pas sur le trajet</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Registraire</strong></td><td style="text-align:left;">Il intervient <strong>avant</strong>, une fois par année : c&#39;est chez lui qu&#39;on loue le nom de domaine. Pendant l&#39;affichage de la page, il ne fait rien.</td></tr><tr><td style="text-align:left;"><strong>Courriel professionnel</strong></td><td style="text-align:left;"><code>info@bistro-exemple.ca</code> utilise le <strong>même nom de domaine</strong>, mais c&#39;est un service complètement séparé du site. Changer d&#39;hébergeur sans précaution peut le briser.</td></tr><tr><td style="text-align:left;"><strong>Service externe</strong></td><td style="text-align:left;">La réservation, le paiement ou la livraison se déclenchent <strong>après</strong> l&#39;affichage de la page, quand la cliente clique. Ce n&#39;est pas le site qui les fait.</td></tr></tbody></table><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mt-5"><strong>Ce corrigé n&#39;est pas la seule réponse acceptable.</strong><br> Plusieurs ordres se défendent — par exemple, on peut placer le certificat SSL/TLS plus loin sur le trajet, ou mettre le nom de domaine à côté du trajet plutôt que dessus. Ce qui compte, c&#39;est que <strong>votre</strong> ordre s&#39;explique. Si votre trajet diffère et que vous savez pourquoi, dites-le pendant la mise en commun. </div></details><p>Suite : <a href="./01-mettre-un-site-en-ligne#le-trajet-d-une-page-web">Séance 1 — Ce qu&#39;il faut pour mettre un site en ligne</a></p>',5))])}const h=r(o,[["render",d]]);export{b as __pageData,h as default};
